records.normalized_output:
NUMBER n.
INPUT(n).
NUMBER left=1.
NUMBER right=n.
LOOP (left<=right) {
    NUMBER middle=(left+right)/2.
    IF (n%middle==0) {
        left=middle+1.
    } ELSE {
        right=middle-1.
    }
}
NUMBER count=0.
NUMBER index=n.
LOOP (index>=1) {
    IF (n%index==0) {
        count++.
    }
    index--.
}
DISPLAYNL(count).

